window.ATLAS.addDetails("circuits.questions",{"questions":{
"q-magnets-0":{"target":{"node":"magnets","href":"../physics/electromagnetism/magnets/#step2"},"prompts":[{"node":"magnets","ask":{"zh":"在磁铁周围撒铁屑，铁屑排成的线从哪极出来、进哪极？哪里排得最密？","en":"Scatter iron filings around a magnet — which pole do the lines leave, which do they enter, and where are they densest?"}},{"node":"vectors","ask":{"zh":"磁感线上的箭头表示什么方向？线上某一点的箭头方向就是那一点磁场的什么？","en":"What direction does an arrow on a field line show? At any point, the arrow's direction is the direction of what?"}}],"reveal":{"zh":"铁屑连成的磁感线从 N 极出、进 S 极，越靠近磁极越密；线上的箭头就是该点磁场的方向。","en":"The filings trace field lines leaving N and entering S, densest near the poles; the arrow on a line at any point is the direction of the field there."},"source":"../physics/electromagnetism/magnets/#step2","lesson":"magnets"},
"q-simple-circuits-0":{"target":{"node":"simple-circuits","href":"../physics/circuits/simple-circuits/#step3"},"prompts":[{"node":"simple-circuits","ask":{"zh":"只有闭合的回路才有电流；如果用一根导线直接连电池两端，电流还经过灯泡吗？","en":"Current needs a closed loop — if a wire connects the battery's two ends directly, does the current still go through the bulb?"}},{"node":"power","ask":{"zh":"同一节电池，电流变大很多倍，导线发热会怎样变？","en":"With the same battery, if the current grows many times larger, what happens to the wire's heating?"}}],"reveal":{"zh":"短路绕过了灯泡，回路电阻极小，电流远大于正常值，导线急剧发热，容易烧坏甚至起火。","en":"A short circuit bypasses the bulb, so the loop's resistance is tiny and the current is far above normal — the wire heats up fast and can burn or catch fire."},"source":"../physics/circuits/simple-circuits/#step3","lesson":"simple-circuits"},
"q-ohms-law-0":{"target":{"node":"ohms-law","href":"../physics/circuits/ohms-law/#step0"},"prompts":[{"node":"simple-circuits","ask":{"zh":"完整闭合的回路里电流处处相同——调高电压，电流怎样变？调大电阻呢？","en":"In a complete closed loop the current is the same everywhere — raise the voltage, what happens to the current? Raise the resistance?"}},{"node":"ohms-law","ask":{"zh":"灯丝的电流-电压曲线是弯的，不是直线——这说明灯丝的电阻是恒定的吗？温度起了什么作用？","en":"A filament's current-voltage curve bends instead of staying straight — does that mean its resistance is constant? What role does temperature play?"}}],"reveal":{"zh":"对定值电阻电流与电压成正比；灯丝发热后电阻变大，曲线变弯，所以电流不再跟电压成正比。","en":"For a fixed resistor current is proportional to voltage; a filament's resistance grows as it heats, bending the curve, so its current no longer tracks voltage proportionally."},"source":"../physics/circuits/ohms-law/#step0","lesson":"ohms-law"},
"q-series-parallel-0":{"target":{"node":"series-parallel","href":"../physics/circuits/series-parallel/#step2"},"prompts":[{"node":"simple-circuits","ask":{"zh":"串联时电流处处相同——拧下一个灯泡，整个回路的电流会怎样？","en":"In series the current is the same everywhere — unscrew one bulb, what happens to the current in the whole loop?"}},{"node":"series-parallel","ask":{"zh":"并联时电压相同、电流按电阻反比分——家里一个灯坏了，其他灯的电压变了吗？为什么还亮？","en":"In parallel the voltage is the same and current divides inversely with resistance — when one home bulb fails, does the voltage on the others change? Why do they stay lit?"}}],"reveal":{"zh":"串联是一条路，断了全灭；并联是各走各的路，电压不变、各支路独立，所以一个坏了其他还亮——这就是家庭电器并联的原因。","en":"Series is a single path — break it and all go dark; parallel gives each bulb its own path at the same voltage, independently, so one failing leaves the rest lit — which is why home appliances are wired in parallel."},"source":"../physics/circuits/series-parallel/#step2","lesson":"series-parallel"},
"q-blackbody-radiation-0":{"target":{"node":"blackbody-radiation","href":"../physics/modern/blackbody-radiation/#step5"},"prompts":[{"node":"blackbody-radiation","ask":{"zh":"经典理论预言黑体在短波处辐射无限大——实际测到的光谱在短波处是发散还是收敛？","en":"Classical theory predicted infinite radiation at short wavelengths — does the measured spectrum diverge or converge there?"}},{"node":"photoelectric-effect","ask":{"zh":"普朗克假设能量一份一份是 hν——这个假设怎样让短波部分的辐射不再发散？","en":"Planck assumed energy comes in chunks of hν — how does that stop the short-wave radiation from diverging?"}}],"reveal":{"zh":"经典理论在短波发散（紫外灾难），与实测不符；普朗克的能量量子 hν 让高频模式难以激发，光谱收敛，量子就此登场。","en":"Classical theory diverged at short wavelengths — the ultraviolet catastrophe — contradicting measurement; Planck's energy quanta hν make high-frequency modes hard to excite, so the spectrum converges, and the quantum was born."},"source":"../physics/modern/blackbody-radiation/#step5","lesson":"blackbody-radiation"},
"q-electric-fields-0":{"target":{"node":"electric-fields","href":"../physics/electromagnetism/electric-fields/#step2"},"prompts":[{"node":"vectors","ask":{"zh":"力是矢量，有大小有方向——画电场时，箭头的方向和长短各表示什么？","en":"Force is a vector with size and direction — when drawing an electric field, what do an arrow's direction and length each show?"}},{"node":"electric-fields","ask":{"zh":"两个点电荷的场怎样叠加？某一点的总场是两个场的和还是差？","en":"How do two point charges' fields combine? At any point, is the total field the sum or the difference of the two?"}},{"node":"superposition","ask":{"zh":"场线和等势线有什么关系？试探电荷放上去会往哪个方向动？","en":"How do field lines relate to equipotential lines? Which way would a released test charge move?"}}],"reveal":{"zh":"用带箭头的场线画电场：方向是正试探电荷受力方向，疏密是强弱；多电荷的场按矢量叠加。","en":"Draw the field with arrows: direction is the force on a positive test charge, density is strength; multiple charges' fields add as vectors."},"source":"../physics/electromagnetism/electric-fields/#step2","lesson":"electric-fields"},
"q-electrochemistry-0":{"target":{"node":"electrochemistry","href":"../chemistry/reactions/electrochemistry/#step2"},"prompts":[{"node":"electric-fields","ask":{"zh":"标准电极电势不同，两个电极接起来为什么会有电压？电压由什么决定？","en":"With different standard electrode potentials, why does joining two electrodes give a voltage? What sets its size?"}},{"node":"electrochemistry","ask":{"zh":"放电时反应物消耗、产物积累——能斯特方程说，浓度变化会让电压升高还是降低？","en":"As discharge consumes reactants and builds up products, does the Nernst equation say the voltage rises or falls?"}},{"node":"electromagnetic-induction","ask":{"zh":"电解和电池放电是互逆过程——充电时外加电压要克服什么？和电磁感应里的能量转换有什么相通处？","en":"Electrolysis reverses battery discharge — what must the charging voltage overcome? What does that share with energy conversion in electromagnetic induction?"}}],"reveal":{"zh":"两电极电势差就是电压；用着用着反应物减少、产物增多，按能斯特方程电压逐渐降低。","en":"The voltage is the difference of the two electrode potentials; as reactants are used up and products build, the Nernst equation drops the voltage."},"source":"../chemistry/reactions/electrochemistry/#step2","lesson":"electrochemistry"},
"q-electromagnetic-induction-0":{"target":{"node":"electromagnetic-induction","href":"../physics/electromagnetism/electromagnetic-induction/#step1"},"prompts":[{"node":"derivative","ask":{"zh":"磁通量变化率就是电压——磁通量变化越快，电压越大还是越小？这和导数有什么关系？","en":"The rate of change of flux is the voltage — faster flux change means bigger or smaller voltage? What does that have to do with a derivative?"}},{"node":"electromagnetic-induction","ask":{"zh":"楞次定律说感应电流总要反抗变化——线圈转动发电时，感应电流的方向什么时候反向？","en":"Lenz's law says the induced current always opposes the change — in a spinning-coil generator, when does the induced current reverse direction?"}},{"node":"oscillation","ask":{"zh":"线圈匀速转动，感应电压随时间是什么形状？为什么是振荡的？","en":"A coil spinning steadily — what shape is the induced voltage over time? Why does it oscillate?"}}],"reveal":{"zh":"法拉第定律：电压等于磁通量变化率；楞次定律定方向——总反抗变化；线圈转动使磁通量周期变化，电压就是交流。","en":"Faraday's law: voltage equals the rate of change of flux; Lenz's law sets the direction — always opposing the change; a spinning coil makes the flux vary periodically, so the voltage alternates."},"source":"../physics/electromagnetism/electromagnetic-induction/#step1","lesson":"electromagnetic-induction"},
"q-magnetic-force-0":{"target":{"node":"magnetic-force","href":"../physics/electromagnetism/magnetic-force/#step1"},"prompts":[{"node":"vectors","ask":{"zh":"带电粒子在磁场中受力，力的方向和速度、磁场各是什么关系？","en":"A charged particle in a magnetic field feels a force — how does its direction relate to the velocity and the field?"}},{"node":"magnetic-force","ask":{"zh":"力总垂直于速度——速度大小变吗？只改变方向的力会让粒子走什么轨迹？","en":"The force is always perpendicular to the velocity — does the speed change? What path does a force that only changes direction produce?"}},{"node":"oscillation","ask":{"zh":"粒子转圈的周期和速度有关吗？质谱仪怎样利用这一点区分粒子？","en":"Does the circling period depend on speed? How does a mass spectrometer use that to tell particles apart?"}}],"reveal":{"zh":"磁场力总垂直于速度，只改方向不改大小，粒子就做圆周运动；周期与速度无关，质谱仪按周期（实际按半径）区分不同质量。","en":"The magnetic force stays perpendicular to velocity, changing direction but not speed, so the particle circles; the period is speed-independent, and a mass spectrometer separates masses by the resulting radius."},"source":"../physics/electromagnetism/magnetic-force/#step1","lesson":"magnetic-force"},
"q-carnot-cycle-0":{"target":{"node":"carnot-cycle","href":"../physics/thermal/carnot-cycle/#step4"},"prompts":[{"node":"carnot-cycle","ask":{"zh":"p–V 图上回路围出的面积是什么？净功和吸热、放热什么关系？","en":"On a p–V diagram, what is the area enclosed by the loop? How do net work, heat in and heat out relate?"}},{"node":"work-energy","ask":{"zh":"效率上限 1 − T_c/T_h 由什么决定？提高热源温度还是降低冷源温度更有效？","en":"What sets the efficiency ceiling 1 − T_c/T_h? Is raising the hot temperature or lowering the cold one more effective?"}}],"reveal":{"zh":"净功就是回路面积，Q_h = W + Q_c；可逆循环的效率只由两端温度定，1 − T_c/T_h 是任何热机都越不过的上限。","en":"Net work is the enclosed area, with Q_h = W + Q_c; a reversible cycle's efficiency depends only on the two temperatures, and 1 − T_c/T_h is a ceiling no heat engine can pass."},"source":"../physics/thermal/carnot-cycle/#step4","lesson":"carnot-cycle"}
}});
